-- Adds the Chamber's past events (from newspaper reports), newest first.
-- Photos are taken automatically from the Gallery, by matching the gallery photo's event name.
-- Safe to run twice: an event with the same title and date is not added again.
-- Run AFTER the gallery photos are uploaded. Needs event_photos.sql to have been run.

with ev(title, event_date, location, description, gallery_name) as (values
 ($t$Export Awareness Camp & E-commerce Export Summit$t$, '2026-09-11 10:00+05:30', 'Bhuj',
  $d$A programme to help small and medium businesses of Kutch sell their products directly to buyers abroad through e-commerce. Officers of the Directorate General of Foreign Trade, FIEO, India Post and private logistics companies explained export procedures, customs, shipping and online marketplaces. More than 200 industrialists and traders took part.$d$,
  'Export Awareness Camp & E-commerce Export Summit'),
 ($t$Seminar on BIS Quality Standards$t$, '2026-08-25 10:00+05:30', 'Bhuj',
  $d$Held jointly with the Bureau of Indian Standards (BIS), Gandhidham. Industrialists and MSMEs were guided on BIS and ISI certification and quality-control orders, and why following quality standards helps local products compete in bigger markets.$d$,
  'BIS Seminar'),
 ($t$Seminar on Industry 4.0 and Startups$t$, '2026-08-14 10:00+05:30', 'Bhuj',
  $d$Organised with the National Productivity Council. Experts spoke about new technology in manufacturing, the "dark factory" concept, startup ideas, funding and Government schemes for industry. Around 200 industrialists attended.$d$,
  null),
 ($t$Honour for Municipality Office-bearers and Development Meeting$t$, '2026-06-22 11:00+05:30', 'Bhuj',
  $d$The Chamber honoured the newly elected office-bearers of Bhuj Municipality and held a meeting on the city's development. Ten suggestions were presented, including Narmada water for Hamirsar lake, a city bus service, traffic management and better infrastructure, along with the need to develop Bhuj as a Mahanagarpalika (city corporation).$d$,
  'Honour for Municipality Office-bearers'),
 ($t$Felicitation of the Chamber President by MP Vinod Chavda$t$, '2026-06-16 11:00+05:30', 'Bhuj',
  $d$On the occasion of 12 years of the Central Government, Kutch MP Vinod Chavda visited the Chamber and felicitated President Anil Gor. Issues of trade, industry, infrastructure, tourism and connectivity in Kutch were discussed.$d$,
  null),
 ($t$Courtesy Meeting with the District Collector$t$, '2026-06-05 11:00+05:30', 'Bhuj',
  $d$Office-bearers of the Chamber and leaders of various trade associations met Collector Anil Ranavasiya. They discussed trade, industry, rail and air connectivity and the future development of Kutch, and spoke about plans for a global convention of Kutchis living abroad to attract investment.$d$,
  null),
 ($t$Talk on "Vyapar ane Adhyatmikta" by Dr. Gyanvatsal Swami$t$, '2026-04-25 18:30+05:30', 'Town Hall, Bhuj',
  $d$The Chamber organised a talk on business and spirituality by Dr. Gyanvatsal Swami. He spoke about excellence in work, honesty in duty and values in business, and how bringing spirituality into trade leads to lasting success. A large number of traders and citizens attended.$d$,
  'Programme with Swaminarayan Saints'),
 ($t$Budget Suggestions Presented to the MP$t$, '2026-01-07 11:00+05:30', 'Bhuj',
  $d$Ahead of the Union Budget, the Chamber gave a memorandum of suggestions for Kutch, including an international airport, international cargo, more rail services and lower GST on gold and silver.$d$,
  'Budget Suggestions Memorandum to MP'),
 ($t$Meeting with the Chief Minister on Land Measurement Issues$t$, '2025-12-03 11:00+05:30', 'Gandhinagar',
  $d$A Chamber delegation raised the problems faced by people in Kutch because of land measurement (survey) issues. The Chief Minister assured quick action.$d$,
  null),
 ($t$Meeting with Prime Minister Narendra Modi$t$, '2025-05-26 11:00+05:30', 'Bhuj',
  $d$During the Prime Minister's visit to Bhuj, Chamber President Anil Gor met him and briefed him about the work of the Chamber and the Global Kutch Federation in connecting Kutchis living in about 180 countries with their homeland. The Prime Minister appreciated their work.$d$,
  'With Prime Minister Narendra Modi'),
 ($t$Traders' Meeting on Boycott of Turkey and Azerbaijan$t$, '2025-05-16 11:00+05:30', 'Bhuj',
  $d$Traders and associations of Kutch, led by the Chamber, decided to boycott trade with Turkey and Azerbaijan in support of the country.$d$,
  null),
 ($t$Meeting with the Collector on Emergency Preparedness$t$, '2025-05-10 11:00+05:30', 'Bhuj',
  $d$During the high alert, the Chamber met the Collector along with various trade associations and assured full support to the administration, including health and other services, so that people of Kutch would face no difficulty.$d$,
  null),
 ($t$Yashgatha Gujarati Award to Anil Gor$t$, '2025-05-01 11:00+05:30', null,
  $d$Chamber President Anil Gor was among four Kutchis honoured with the Yashgatha Gujarati award, presented by former Chief Minister Vijay Rupani.$d$,
  'Yashgatha Gujarati Award to Anil Gor'),
 ($t$Meeting with Chief Minister Bhupendra Patel$t$, '2025-03-27 11:00+05:30', 'Gandhinagar',
  $d$A Chamber delegation met Chief Minister Bhupendra Patel and presented the demand for city-corporation (Mahanagarpalika) status for Bhuj, along with other issues of the city and district.$d$,
  'Meeting with CM Bhupendra Patel'),
 ($t$Income Tax Outreach Programme on Exemption Provisions$t$, '2025-01-15 16:00+05:30', 'ICAI Bhuj Branch, Bhuj',
  $d$Held with the Income Tax Department and the ICAI Bhuj Branch for charitable trusts and organisations. Officers explained the exemption provisions, including section 80-G registration, returns and compliance.$d$,
  'Income Tax Outreach Programme on Exemptions'),
 ($t$Madhapar Vepari Association Get-together$t$, '2024-11-17 18:00+05:30', 'Madhapar',
  $d$The Chamber took part in the get-together of the Madhapar Vepari Association, where traders discussed their issues and ways to work together.$d$,
  null),
 ($t$ICAI MSME & Startup Yatra$t$, '2024-09-17 10:00+05:30', 'Bhuj',
  $d$A programme on financial and tax awareness for MSMEs and startups, held with the ICAI Bhuj Branch.$d$,
  'ICAI MSME & Startup Yatra'),
 ($t$Dialogue with Non-Resident Kutchis$t$, '2024-04-06 18:00+05:30', 'Bhuj',
  $d$Held with the Global Kutch Federation, so that Kutchis living abroad could share their problems and ideas, strengthen trade links and stay connected with their homeland.$d$,
  null),
 ($t$Talk on "Foreign Policy for Viksit Bharat"$t$, '2024-03-30 18:00+05:30', 'Bhuj',
  $d$A discussion for traders and citizens on India's foreign policy and its role in building a developed India (Viksit Bharat).$d$,
  'Foreign Policy for Viksit Bharat'),
 ($t$Air India Bhuj–London Flight Launch$t$, '2024-03-01 11:00+05:30', 'Bhuj Airport',
  $d$The Chamber took part in the launch of Air India's new Airbus service from Bhuj to Mumbai with connections to London. The first flight carried passengers bound for London, a long-standing demand of the Chamber and Kutchis living abroad.$d$,
  'Air India Bhuj-London Flight Launch'),
 ($t$Cyber Crime Awareness Seminar with West Kutch Police$t$, '2024-02-01 11:00+05:30', 'Bhuj',
  $d$Organised jointly by West Kutch Police and the Chamber under the chairmanship of the Superintendent of Police. Officers explained how online frauds happen, the main reasons people fall for them and how to report cyber crime quickly on helpline 1930. Traders and leaders of many associations attended.$d$,
  'Cyber Crime Awareness Programme with West Kutch Police'),
 ($t$Seminar on Income Tax Section 43(B)(h)$t$, '2024-01-29 17:00+05:30', 'Bhuj',
  $d$Experts explained the new income tax rule on timely payments to MSME suppliers under section 43(B)(h), and what businesses must do to comply.$d$,
  'Income Tax Section 43(B)(h) Seminar'),
 ($t$Seminar on Digital Currency$t$, '2024-01-11 17:00+05:30', 'Bhuj',
  $d$A seminar for traders on digital currency and digital payments, and what they mean for business.$d$,
  null),
 ($t$Meeting with the US Consul$t$, '2024-01-08 11:00+05:30', 'Bhuj',
  $d$The Chamber met the US Consul and her team to discuss trade, investment and business links between Kutch and the United States, and the facilities Kutch needs to attract foreign investors.$d$,
  'Meeting with US Consul')
)
insert into public.events (title, event_date, location, description, photos)
select ev.title, ev.event_date::timestamptz, ev.location, ev.description,
       coalesce((select jsonb_agg(g.image_url order by g.sort_order nulls last, g.created_at)
                 from (select image_url, sort_order, created_at from public.gallery_images
                       where ev.gallery_name is not null and event_name = ev.gallery_name
                       order by sort_order nulls last, created_at limit 20) g), '[]'::jsonb)
from ev
where not exists (select 1 from public.events e where e.title = ev.title and e.event_date = ev.event_date::timestamptz);
